 if(old.type==='entrada'){const costRaw=prompt('Custo por unidade (R$)',old.price);if(costRaw===null)return;const price=Number(costRaw.replace(',','.'));if(!costRaw.trim()||!Number.isFinite(price)||price<0)return alert('Custo inválido.');const batch=prompt('Lote do fabricante',old.batch||'');if(batch===null)return;const expiry=prompt('Validade (AAAA-MM-DD; vazio se não houver)',old.expiry||'');if(expiry===null)return;if(expiry&&!validIsoDate(expiry))return alert('Validade inválida.');updated={...updated,price,batch,expiry}}
