const BACKUP_KEYS=[HERD_KEY,LOSS_KEY,OP_LOTS_KEY,STORAGE_KEY,STOCK_KEY,STOCK_MIN_KEY,PH_KEY,EXPENSE_KEY,REVENUE_KEY,ANIMAL_SALES_KEY];
function backupPage(){return '<div class="page"><div class="form-intro"><div><h2>Backup da propriedade</h2><p>Guarde uma cópia dos dados deste navegador para recuperar ou transferir seus registros.</p></div></div><section class="form-panel"><h3>Exportar dados</h3><p>O arquivo inclui simulações, lotes operacionais independentes, estoque, farmácia, rebanho individual, baixas, despesas, receitas e vendas registradas. Guarde-o em local seguro.</p><button id="download-backup" class="primary-btn">Baixar backup completo</button></section><section class="form-panel"><h3>Restaurar dados</h3><p>Selecione um backup gerado pelo Gestão Pecuária. A restauração substitui os registros atuais deste navegador; faça um backup antes de prosseguir.</p><label><span>Arquivo de backup (.json)</span><input id="backup-file" type="file" accept=".json,application/json"></label><div class="preview-form-actions"><button id="restore-backup" class="secondary-btn">Conferir e restaurar backup</button></div><p id="backup-feedback" role="status"></p></section></div>'}
function bindBackup(){
 const download=document.querySelector('#download-backup');
 if(download)download.onclick=()=>{
  persist();
  const data={format:'gestao-pecuaria-backup',version:1,exportedAt:new Date().toISOString(),records:{}};
  for(const key of BACKUP_KEYS){const raw=localStorage.getItem(key);data.records[key]=raw===null?(key===HERD_KEY?herdAnimals:key===LOSS_KEY?herdLosses:key===OP_LOTS_KEY?operationalLots:key===STORAGE_KEY?lots:key===STOCK_KEY?stock:key===STOCK_MIN_KEY?stockMinimums:key===PH_KEY?pharmacy:key===EXPENSE_KEY?expenses:key===ANIMAL_SALES_KEY?animalSales:revenues):JSON.parse(raw)}
  const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));
  const a=document.createElement('a');a.href=url;a.download='gestao-pecuaria-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 };
 const restore=document.querySelector('#restore-backup');
 if(restore)restore.onclick=async()=>{
  const file=document.querySelector('#backup-file').files[0],feedback=document.querySelector('#backup-feedback');
  if(!file){feedback.textContent='Selecione um arquivo de backup.';return}
  let data;
  try{data=JSON.parse(await file.text())}catch{feedback.textContent='Arquivo inválido: não foi possível ler o JSON.';return}
  if(!data||data.format!=='gestao-pecuaria-backup'||data.version!==1||!data.records||typeof data.records!=='object'||Array.isArray(data.records)){feedback.textContent='Arquivo incompatível com o backup do Gestão Pecuária.';return}
  if(!BACKUP_KEYS.filter(k=>k!==REVENUE_KEY&&k!==ANIMAL_SALES_KEY&&k!==OP_LOTS_KEY&&k!==HERD_KEY&&k!==LOSS_KEY).every(k=>Object.prototype.hasOwnProperty.call(data.records,k))||!Array.isArray(data.records[STORAGE_KEY])||!data.records[STORAGE_KEY].every(l=>l&&typeof l==='object'&&l.id&&l.data&&typeof l.data==='object'&&Array.isArray(l.data.otherCosts))||!data.records[STOCK_KEY]||!Array.isArray(data.records[STOCK_KEY].entries)||!Array.isArray(data.records[STOCK_KEY].batches)||!data.records[PH_KEY]||!Array.isArray(data.records[PH_KEY].moves)||!Array.isArray(data.records[EXPENSE_KEY])||(Object.prototype.hasOwnProperty.call(data.records,REVENUE_KEY)&&!Array.isArray(data.records[REVENUE_KEY]))||(Object.prototype.hasOwnProperty.call(data.records,ANIMAL_SALES_KEY)&&!Array.isArray(data.records[ANIMAL_SALES_KEY]))){feedback.textContent='O backup não contém a estrutura esperada. Nenhum dado foi alterado.';return}
  if(Object.prototype.hasOwnProperty.call(data.records,OP_LOTS_KEY)&&(!Array.isArray(data.records[OP_LOTS_KEY])||!data.records[OP_LOTS_KEY].every(l=>l&&l.id&&l.data&&typeof l.data.name==='string'))){feedback.textContent='Lotes operacionais inválidos no backup.';return}
  if([HERD_KEY,LOSS_KEY].some(k=>Object.prototype.hasOwnProperty.call(data.records,k)&&!Array.isArray(data.records[k]))){feedback.textContent='Registros de rebanho inválidos no backup.';return}
  if(data.records[STOCK_MIN_KEY]!==null&&(typeof data.records[STOCK_MIN_KEY]!=='object'||Array.isArray(data.records[STOCK_MIN_KEY]))){feedback.textContent='Limites de estoque inválidos. Nenhum dado foi alterado.';return}
  if(!confirm('ATENÇÃO: restaurar este arquivo substituirá TODOS os lotes, estoques, registros da farmácia e despesas salvos neste navegador. Deseja continuar?'))return;
  const before={};try{
   for(const key of BACKUP_KEYS)before[key]=localStorage.getItem(key);
   for(const key of BACKUP_KEYS){const val=(key===REVENUE_KEY||key===ANIMAL_SALES_KEY||key===OP_LOTS_KEY||key===HERD_KEY||key===LOSS_KEY)&&!Object.prototype.hasOwnProperty.call(data.records,key)?[]:data.records[key];if(val===null)localStorage.removeItem(key);else localStorage.setItem(key,JSON.stringify(val))}
  }catch(err){for(const key of BACKUP_KEYS)try{if(before[key]===null)localStorage.removeItem(key);else if(before[key]!==undefined)localStorage.setItem(key,before[key])}catch{}feedback.textContent='Não foi possível restaurar os dados. Verifique o espaço disponível no navegador.';return}
  alert('Backup restaurado. A página será recarregada para exibir os dados recuperados.');location.reload();
 };
}
function shell(c){return `<div class="app-shell"><aside class="open"><div class="brand"><span>${icon('♜')}</span><div><b>GESTÃO</b><strong>PECUÁRIA</strong></div></div><nav><small>VISÃO GERAL · SIMULAÇÕES</small><button data-page="lotes" class="${page==='lotes'?'active':''}">${menuIcon('lotes')} Lotes</button><button data-page="dados" class="${page==='dados'?'active':''}">${menuIcon('dados')} Análise dos lotes</button><button data-page="dashboard" class="${page==='dashboard'?'active':''}">${menuIcon('dashboard')} Dashboard</button><small>GESTÃO</small><button data-page="estoque" class="${page==='estoque'?'active':''}">${menuIcon('estoque')} Estoque de ração</button><button data-page="farmacia" class="${page==='farmacia'?'active':''}">${menuIcon('farmacia')} Farmácia</button><button data-page="rebanho" class="${page==='rebanho'?'active':''}">${menuIcon('lotes')} Rebanho</button><button data-page="receitas" class="${page==='receitas'?'active':''}">${menuIcon('receitas')} Receitas</button><button data-page="despesas" class="${page==='despesas'?'active':''}">${menuIcon('despesas')} Despesas</button><button data-page="backup" class="${page==='backup'?'active':''}">${menuIcon('backup')} Backup</button><button data-page="relatorios" class="${page==='relatorios'?'active':''}">${menuIcon('relatorios')} Relatórios</button></nav><div class="sidebar-foot"><div class="avatar">GP</div><div><b>Minha propriedade</b><span>Plano demonstração</span></div></div></aside><main><header><div><p>Confinamento <span>•</span> Ciclo atual</p><h1>${page==='dashboard'?'Visão geral do lote':page==='dados'?'Análise dos lotes':page==='lotes'?'Simulações de viabilidade':page==='rebanho'?'Rebanho':page==='estoque_animais'?'Estoque do rebanho':page==='compra_animais'?'Compra de animais':page==='venda_animais'?'Venda de animais':page==='estoque'?'Estoque de ração':page==='farmacia'?'Farmácia':page==='despesas'?'Despesas realizadas':page==='receitas'?'Receitas':page==='backup'?'Backup da propriedade':'Relatórios'}</h1></div><div class="status"><i></i> Prévia local navegável</div></header>${c}</main></div><div class="preview-note"><b>PRÉVIA SEM DEPENDÊNCIAS</b> · Dados mantidos nesta sessão</div>`}
function dashboard(){const m=calculateLot({...state,exits:[],deaths:0,otherExits:0}),remaining=safe(state.animals),p=Array.from({length:8},(_,i)=>state.entryWeight+m.dailyGain*Math.round(state.days*i/7)),max=Math.max(...p);return `<div class="page"><section class="welcome"><div><span>SIMULAÇÃO DE VIABILIDADE</span><h2>O ganho médio diário estimado é de <b>${num(m.dailyGain,2)} kg</b> por dia.</h2><p>Os indicadores são projeções para apoiar a decisão de compra, não resultados realizados.</p></div><button data-page="dados">${icon('⚙')} Atualizar dados</button></section><div class="metrics-grid">${metric('Animais simulados',`${remaining} cabeças`,'♜')}${metric('Peso de entrada',`${num(state.entryWeight)} kg`,'⚖')}${metric('Peso atual / saída',`${num(state.currentWeight)} kg`,'⚖')}${metric('GMD',`${num(m.dailyGain,2)} kg/dia`,'↗')}${metric('Dias de confinamento',`${state.days} dias`,'▣')}${metric('Nutrição prevista',brl(m.feedTotal),'▣')}${metric('Custo cabeça/dia',brl(m.costPerHeadDay),'▤')}${metric('Custo da @ produzida (PV)',brl(m.producedArrobaCost),'R$')}${metric('Investimento total',brl(m.investment),'▤')}</div><div class="financial">${metric('Receita projetada',brl(m.revenue),'↗','featured')}${metric('Lucro projetado por animal',brl(m.marginPerAnimal),'◉','featured',m.marginPerAnimal>=0?'positive':'negative')}${metric('Lucro ou prejuízo projetado',brl(m.result),'R$','featured',m.result>=0?'positive':'negative')}${metric('ROI estimado',`${num(m.roi,2)}%`,'▥','featured',m.roi>=0?'positive':'negative')}</div><p><small>Receita projetada = quantidade de animais simulados × peso de carcaça estimado × preço de venda (conforme unidade escolhida). Lucro ou prejuízo projetado = receita projetada − compra prevista − nutrição prevista − outros custos previstos. Valores hipotéticos, não recebimentos nem lucro realizado.</small></p><div class="charts"><article class="panel"><div class="panel-title"><div><h3>Evolução de peso</h3><p>Projeção com base no GMD atual</p></div></div><div class="chart-bars">${p.map((v,i)=>`<div style="height:${v/max*90}%"><span>D${Math.round(state.days*i/7)}</span></div>`).join('')}</div></article><article class="panel"><div class="panel-title"><div><h3>Composição do investimento</h3><p>Distribuição por categoria</p></div></div><div class="cost-bars">${[['Compra',m.purchaseTotal,'#c9b482'],['Nutrição',m.feedTotal,'#28594b'],['Outros',m.otherCostsTotal,'#82a99c']].map(([n,v,c])=>`<div class="cost-bar"><span>${n}</span><i style="width:${v/m.investment*100}%;background:${c}"></i></div>`).join('')}</div></article></div><div class="summary-strip"><span><small>@ produzida equivalente (PV)</small><b>${num(m.liveArrobasProducedPerAnimal,2)} @/animal</b></span><span><small>Peso de carcaça projetado</small><b>${num(m.carcassWeightPerAnimal,1)} kg/animal</b></span><span><small>@ de carcaça na saída</small><b>${num(m.carcassArrobasPerAnimal,2)} @/animal</b></span></div><div class="insight"><span>${icon('◉')}</span><div><b>Ponto de equilíbrio</b><p>O preço mínimo para cobrir aquisição e custos é <strong>${brl(m.breakEven)}/@</strong>.</p></div><small>Venda esperada<br><b>${brl(state.salePrice)}/@</b></small></div><div class="summary-strip"><span><small>Preço máximo de compra</small><b>${brl(m.maxPurchasePriceKg)}/kg</b></span><span><small>Compra máxima por animal</small><b>${brl(m.maxPurchasePerAnimal)}</b></span><span><small>Custo operacional por animal</small><b>${brl(m.operationalPerAnimal)}</b></span></div></div>`}
const unitSelect=(l,k,opts)=>`<label class="field"><span>${l}</span><div class="input-wrap"><select data-unit="${k}">${opts.map(o=>`<option value="${o[0]}" ${state[k]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div></label>`;
const costField=(c,i)=>`<div class="cost-row"><input data-cost-name="${i}" value="${c.name}"><div class="money"><span>${c.basis==='receita_pct'?'%':'R$'}</span><input data-cost-value="${i}" type="number" min="0" step="0.01" value="${c.value}"></div><select data-cost-basis="${i}"><option value="animal" ${c.basis==='animal'?'selected':''}>Por animal</option><option value="dia" ${c.basis==='dia'?'selected':''}>Por dia (lote)</option><option value="lote" ${c.basis==='lote'?'selected':''}>Total do lote</option><option value="receita_pct" ${c.basis==='receita_pct'?'selected':''}>% da receita de venda</option></select></div>`;
const field=(l,k,s='')=>`<label class="field"><span>${l}</span><div class="input-wrap"><input data-key="${k}" type="${k==='name'?'text':'number'}" min="0" step="0.01" value="${state[k]}">${s?`<small>${s}</small>`:''}</div></label>`;
let lotAnalysisTab='dados';
function form(){const activeLot=lots.find(l=>l.id===activeId),m=calculateLot({...state,referenceDate:new Date().toISOString().slice(0,10)}),exitRows=state.exits||[],deaths=exitRows.length?exitRows.filter(x=>x.type==='morte'&&x.confirmed!==false).reduce((s,x)=>s+safe(x.quantity),0):safe(state.deaths),otherExits=exitRows.length?exitRows.filter(x=>x.type==='outra'&&x.confirmed!==false).reduce((s,x)=>s+safe(x.quantity),0):safe(state.otherExits),currentAnimals=Math.max(0,safe(state.animals)-deaths-otherExits),mortality=safe(state.animals)?deaths/safe(state.animals)*100:0;return `<div class="page"><div class="form-intro"><div><h2>Análise de viabilidade</h2><p>Simule premissas para decidir sobre a compra. Nenhum valor desta tela representa uma operação realizada.</p></div></div><div class="expense-subnav" role="tablist" aria-label="Seções da análise do lote">${[['dados','Dados da simulação'],['economia','Compra, nutrição e venda'],['custos','Custos operacionais']].map(([id,label])=>'<button type="button" role="tab" data-analysis-tab="'+id+'" aria-selected="'+(lotAnalysisTab===id?'true':'false')+'" class="'+(lotAnalysisTab===id?'active':'')+'">'+label+'</button>').join('')}</div><section data-analysis-group="dados" class="form-panel"><div class="section-title"><span>01</span><div><h3>Dados do lote</h3><p>Informações zootécnicas</p></div></div><div class="form-grid">${field('Nome do lote','name')}${field('Animais de entrada','animals','cabeças')}${field('Peso médio de entrada','entryWeight','kg')}${field('Peso atual / saída','currentWeight','kg')}${field('Dias no sistema','days','dias')}${field('Rendimento de carcaça','carcassYield','%')}</div><div class="movement-box"><h3>Custo de nutrição estimado</h3><p>Projeção para a quantidade inicial de animais durante todo o período simulado, sem baixas operacionais.</p><div class="summary-strip"><span><small>Animais simulados</small><b>${num(state.animals,0)} cabeças</b></span><span><small>Período estimado</small><b>${num(state.days,0)} dias</b></span><span><small>Nutrição estimada</small><b>${brl(safe(state.animals)*safe(state.days)*safe(state.intake)*safe(state.dietCost))}</b></span></div></div><div class="calculated"><span>↗ GMD calculado</span><b>${num(m.dailyGain,2)} kg/dia</b><small>Ganho: ${num(m.gain)} kg · ${num(m.liveArrobasProducedPerAnimal,2)} @ eq. PV/animal</small></div><div class="summary-strip"><span><small>@ produzida equivalente (PV)</small><b>${num(m.liveArrobasProducedPerAnimal,2)} @/animal</b></span><span><small>Peso de carcaça projetado</small><b>${num(m.carcassWeightPerAnimal,1)} kg/animal</b></span><span><small>@ de carcaça na saída</small><b>${num(m.carcassArrobasPerAnimal,2)} @/animal</b></span></div></section><section data-analysis-group="economia" class="form-panel"><div class="section-title"><span>02</span><div><h3>Premissas de compra, nutrição e venda</h3><p>Valores hipotéticos para a decisão</p></div></div><div class="form-grid">${field('Peso de compra','purchaseWeight','kg')}${unitSelect('Unidade do preço de compra','purchaseUnit',[['kg','Por kg'],['arroba','Por arroba (@)']])}${field('Preço de compra','purchasePrice',state.purchaseUnit==='kg'?'R$/kg':'R$/@')}${unitSelect('Unidade do preço de venda','saleUnit',[['kg','Por kg'],['arroba','Por arroba (@)']])}${field('Preço esperado de venda','salePrice',state.saleUnit==='kg'?'R$/kg':'R$/@')}${field('Consumo de matéria natural','intake','kg/animal/dia')}${field('Custo da dieta','dietCost','R$/kg')}</div><div class="summary-strip"><span><small>Compra total</small><b>${brl(m.purchaseTotal)}</b></span><span><small>Nutrição do lote</small><b>${brl(m.feedTotal)}</b></span><span><small>Receita projetada</small><b>${brl(m.revenue)}</b></span></div><div class="preview-form-actions"><button data-page="dashboard">Ver dashboard atualizado</button></div></section><section data-analysis-group="custos" class="form-panel"><div class="section-title"><span>03</span><div><h3>Custos operacionais</h3><p>Sanidade, mão de obra, fretes, comissões e outras despesas</p></div></div><div class="cost-list">${state.otherCosts.map(costField).join('')}</div></section></div>`}
function actualMetrics(item){const a=item.actual;if(!a)return null;const base=item.projection||item.data,actualData={...JSON.parse(JSON.stringify(base)),currentWeight:a.saleWeight,days:a.days,carcassYield:a.carcassYield,intake:a.intake,dietCost:a.dietCost,salePrice:a.salePrice,saleUnit:a.saleUnit},calc=calculateLot(actualData),investment=calc.investment+safe(a.extraCosts),result=calc.revenue-investment;return {...calc,investment,result,roi:investment?result/investment*100:0,marginPerAnimal:actualData.animals?result/actualData.animals:0}}
function lotsPage(){return `<div class="page"><div class="form-intro"><div><h2>Simulações de viabilidade</h2><p>Simule cenários antes de decidir a compra. Criar ou editar uma simulação não registra compras nem movimenta o financeiro.</p></div><button id="new-lot" class="primary-btn">+ Nova simulação</button></div><div class="lots-grid">${lots.map((item,i)=>{const m=calculateLot({...item.data,exits:[],deaths:0,otherExits:0});return `<article class="lot-card"><div class="lot-card-head"><div><span class="lot-status ${item.status}">${item.status==='ativo'?'Ativo':'Finalizado'}</span><h3>${item.data.name}</h3></div><b>${item.data.animals} animais de entrada</b></div><div class="lot-kpis"><span><small>GMD</small><b>${num(m.dailyGain,2)} kg/dia</b></span><span><small>Dias</small><b>${item.data.days}</b></span><span><small>Resultado</small><b>${brl(m.result)}</b></span><span><small>ROI</small><b>${num(m.roi,2)}%</b></span></div><div class="lot-actions"><button data-open-lot="${i}">Abrir dashboard</button>${item.status==='ativo'?'<button data-edit-lot="'+i+'">Editar</button>':''}<button class="secondary-btn" data-status-lot="${i}">${item.status==='ativo'?'Finalizar ciclo':'Reabrir ciclo'}</button>${'<button class="secondary-btn" data-delete-lot="'+i+'">Excluir simulação</button>'}</div></article>`}).join('')}</div></div>`}
const reportCurrentHeads=item=>Math.max(0,safe(item.data.animals)-(item.data.exits||[]).filter(e=>e.confirmed!==false&&safe(e.quantity)>0).reduce((n,e)=>n+safe(e.quantity),0));
function reportsPage(){const rows=operationalLots.map(l=>{const id=l.id,feed=stock.batches.filter(x=>x.lotId===id).reduce((n,x)=>n+safe(x.cost),0),purchase=expenses.filter(x=>x.lotId===id&&x.category===ANIMAL_PURCHASE_CATEGORY).reduce((n,x)=>n+safe(x.value),0),other=expenses.filter(x=>x.lotId===id&&x.category!==ANIMAL_PURCHASE_CATEGORY).reduce((n,x)=>n+safe(x.value),0),received=revenues.filter(x=>x.lotId===id).reduce((n,x)=>n+safe(x.value),0),negotiated=animalSales.filter(x=>x.lotId===id).reduce((n,x)=>n+safe(x.value),0);return {name:l.data.name,feed,purchase,other,received,negotiated}});return '<div class="page"><div class="form-intro"><div><h2>Relatórios operacionais</h2><p>Somente lançamentos efetivos da Gestão. Nenhuma projeção da Visão Geral entra neste relatório. Vendas negociadas não são automaticamente recebimentos.</p></div></div><div class="expense-table-scroll"><table class="report-table"><thead><tr><th>Lote operacional</th><th>Compra de animais</th><th>Nutrição registrada</th><th>Outras despesas</th><th>Vendas negociadas</th><th>Recebimentos</th><th>Saldo parcial de caixa*</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+escapeText(x.name)+'</td><td>'+brl(x.purchase)+'</td><td>'+brl(x.feed)+'</td><td>'+brl(x.other)+'</td><td>'+brl(x.negotiated)+'</td><td>'+brl(x.received)+'</td><td>'+brl(x.received-x.purchase-x.feed-x.other)+'</td></tr>').join('')+'</tbody></table></div><p><small>*Saldo parcial com base nos registros disponíveis; não representa lucro realizado. Batidas são custos de produção e não necessariamente pagamentos do período. Despesas gerais não foram rateadas.</small></p></div>'}
function render(){if(!lots.length&&(page==='dashboard'||page==='dados'))page='lotes';persist();document.querySelector('#root').innerHTML=shell(page==='dashboard'?dashboard():page==='lotes'?lotsPage():page==='relatorios'?reportsPage():page==='estoque'?stockPage():page==='farmacia'?pharmacyPage():page==='despesas'?expensesPage():page==='receitas'?revenuePage():page==='rebanho'?herdPage():page==='compra_animais'?purchasePage():page==='venda_animais'?purchasePage():page==='estoque_animais'?animalStockPage():page==='backup'?backupPage():form());if(page==='dados'){document.querySelectorAll('[data-analysis-group]').forEach(el=>el.hidden=el.dataset.analysisGroup!==lotAnalysisTab);document.querySelectorAll('[data-analysis-tab]').forEach(el=>el.onclick=()=>{lotAnalysisTab=el.dataset.analysisTab;render()})}if(page==='estoque')bindStock();if(page==='farmacia')bindPharmacy();if(page==='despesas')bindExpenses();if(page==='receitas')bindRevenue();if(page==='rebanho')bindHerd();if(page==='compra_animais'||page==='venda_animais')bindPurchase();if(page==='backup')bindBackup();document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{page=e.dataset.page;render()});document.querySelectorAll('[data-key]').forEach(e=>e.onchange=()=>{state[e.dataset.key]=e.type==='number'?Number(e.value):e.value;render()});document.querySelectorAll('[data-unit]').forEach(e=>e.onchange=()=>{state[e.dataset.unit]=e.value;render()});document.querySelectorAll('[data-cost-name]').forEach(e=>e.onchange=()=>{state.otherCosts[+e.dataset.costName].name=e.value;render()});document.querySelectorAll('[data-cost-value]').forEach(e=>e.onchange=()=>{state.otherCosts[+e.dataset.costValue].value=Number(e.value);render()});document.querySelectorAll('[data-cost-basis]').forEach(e=>e.onchange=()=>{state.otherCosts[+e.dataset.costBasis].basis=e.value;render()});document.querySelectorAll('[data-open-lot]').forEach(e=>e.onclick=()=>{activeId=lots[+e.dataset.openLot].id;Object.assign(state,lots[+e.dataset.openLot].data);page='dashboard';render()});document.querySelectorAll('[data-edit-lot]').forEach(e=>e.onclick=()=>{activeId=lots[+e.dataset.editLot].id;Object.assign(state,lots[+e.dataset.editLot].data);page='dados';render()});document.querySelectorAll('[data-status-lot]').forEach(e=>e.onclick=()=>{const l=lots[+e.dataset.statusLot];if(l.status==='ativo'){l.status='finalizado';l.finalizedAt=new Date().toISOString().slice(0,10);l.projection=JSON.parse(JSON.stringify(l.data));delete l.actual;delete l.actualConfirmed}else{l.status='ativo';delete l.finalizedAt}persist();render()});document.querySelectorAll('[data-delete-lot]').forEach(e=>e.onclick=()=>{const index=+e.dataset.deleteLot,l=lots[index];if(!l)return;if(!window.confirm('Excluir a simulação "'+l.data.name+'"? Esta ação não pode ser desfeita. Os dados da Gestão não serão alterados.'))return;const remaining=lots.filter(x=>x.id!==l.id);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(remaining));if(localStorage.getItem(STORAGE_KEY)!==JSON.stringify(remaining))throw Error('Falha ao verificar gravação');}catch(err){alert('Não foi possível salvar a exclusão neste navegador. Verifique se o armazenamento local está permitido e tente novamente.');return;}lots=remaining;if(activeId===l.id){activeId=lots[0]?.id||null;if(lots[0])Object.assign(state,lots[0].data)}if(!lots.length)page='lotes';render()});document.querySelectorAll('[data-compare]').forEach(e=>e.onchange=()=>{const id=e.dataset.compare;if(window.compareIds.includes(id))window.compareIds=window.compareIds.filter(x=>x!==id);else if(window.compareIds.length<3)window.compareIds.push(id);render()});const clearCompare=document.querySelector('#clear-compare');if(clearCompare)clearCompare.onclick=()=>{window.compareIds=[];render()};const n=document.querySelector('#new-lot');if(n)n.onclick=()=>{const data=JSON.parse(JSON.stringify(lots.length?state:defaultSimulationData));data.name='Simulação '+String(lots.length+1).padStart(2,'0');const id='lote-'+Date.now();lots.push({id,status:'ativo',data,startedAt:new Date().toISOString().slice(0,10)});activeId=id;Object.assign(state,data);page='dados';render()}}window.addEventListener('change',e=>{if(e.target.id==='report-status'){window.reportStatus=e.target.value;render()}if(e.target.id==='report-lot'){window.reportLot=e.target.value;render()}});window.addEventListener('click',e=>{const row=e.target.closest&&e.target.closest('[data-report-lot]');if(row){window.reportLot=row.dataset.reportLot;render()}if(e.target.id==='clear-report'){window.reportStatus='todos';window.reportLot='todos';render()}});
render();